import{_ as e,H as o,f as a,i as n}from"./chunks/framework.CGh9YNlq.js";const m=JSON.parse('{"title":"About Prompting","description":"","frontmatter":{},"headers":[],"relativePath":"notes/Prompting.md","filePath":"notes/Prompting.md"}'),i={name:"notes/Prompting.md"};function r(s,t,p,l,u,d){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="about-prompting" tabindex="-1">About Prompting <a class="header-anchor" href="#about-prompting" aria-label="Permalink to &quot;About Prompting&quot;">​</a></h1><p>Prompting in Generative AI is basically how you talk to the LLMs to get what you want. It&#39;s the practice of designing the input text-the&quot;prompt&quot;-so the model produces a useful, accurate, or specific response.</p><p>How to build a strong Prompt?</p><ul><li>adding context, more effective refining and detailing</li><li>Specifying format</li><li>Providing examples(few-shot prompting)</li><li>Setting a role</li></ul><h1 id="about-learning" tabindex="-1">About Learning <a class="header-anchor" href="#about-learning" aria-label="Permalink to &quot;About Learning&quot;">​</a></h1><p>About In-Context Learning</p><p>In &quot;traditional&quot; ML, where models are predominantly trained for single problems like classifications or regressions, models require extensive training to adapt their weights or parameters to a new task. But you can use LLMs for a wide variety of tasks by changing just the prompt without changing the weights.</p><p>About Zero-Shot Learning:</p><p>Zero-shot learning involves instructing a model to perform a task without providing any examples. This technique relies on the model&#39;s pretrained knowledge and its ability to understand natural language instructions.</p><p>About Few-Shot Learning:</p><p>Few-shot learning extends this approach by including a small number of examples in the prompt. The examples serve as demonstrations that help the model understand the task&#39;s structure and expected output format, and the model then applieds that structure to new instances.</p>',11)])])}const g=e(i,[["render",r]]);export{m as __pageData,g as default};
